function cleanup(stopOral=true){photoMount?.destroy();photoMount=null;autoPhotoMount?.destroy();autoPhotoMount=null;unmountScene();unmountScene=()=>{};cancelSuccess();answerCelebrated=false;rmsMount?.destroy();rmsMount=null;syllablePlayer.stop();kaluluUnmount?.();kaluluUnmount=null;if(stopOral)oralCheck.stop();speedMount?.destroy();speedMount=null;planMount?.destroy();planMount=null;phonemePlayer.stop();gardenCelebration=false;readingProgress=null;clearTimeout(nextWordTimer);nextWordTimer=null;conversation.reset();editTaskIndex=null;tutorVoice.stop();tutorHint=false;mediaEpoch++;micPending=false;clearTimeout(recordTimer);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;recording=false;if(recordURL)URL.revokeObjectURL(recordURL);recordURL=null;reader.stop();speaking=false;mediaMessage='';}
function voicePicker(){const voices=(window.speechSynthesis?.getVoices()||[]).filter(v=>/^fr(?:-|_)/i.test(v.lang));return voices.length?`<label class="voice-picker">Voix de lecture <select id="reading-voice"><option value="">Narratrice IA · français québécois</option>${voices.map(v=>`<option value="${esc(v.voiceURI)}" ${state.readingVoiceURI===v.voiceURI?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('')}</select></label>`:'';}
function speedControl(){const speed=playbackSpeed(state.readingSpeed);return `<div class="speed-control"><label for="reading-speed">🐢 Vitesse de lecture 🐇 <output id="speed-value">${speed.toFixed(1).replace('.',',')} ×</output></label><input id="reading-speed" type="range" min="0.6" max="1.5" step="0.1" value="${speed}" aria-valuetext="${speed} fois la vitesse de départ"><div class="speed-labels"><span>Plus lent</span><span>Plus rapide</span></div></div>`;}
function audio(){return `<details class="reading-options"><summary>🔊 Écouter le texte · vitesse et voix</summary><div class="reading-dock"><div class="audio"><button data-action="listen">▶ Écouter</button><button data-action="silence" aria-label="Arrêter l’écoute">■ Arrêter</button></div>${speedControl()}</div><p class="audio-status" role="status">${esc(voiceMessage||'Écoute la narratrice, puis essaie à ton tour.')}</p><details class="reading-settings"><summary>🎙 Mon studio et ma voix</summary>${voicePicker()}<p>Enregistre ta lecture pour la réécouter avec un adulte. Elle reste sur cet appareil et s’efface en quittant l’activité.</p><button data-action="record" ${recording||micPending?'disabled':''}>Enregistrer ma voix</button><button data-action="stop-record" ${!recording?'disabled':''}>Terminer</button><p role="status">${esc(mediaMessage)}</p>${recordURL?`<audio controls src="${recordURL}"></audio>`:''}</details></details>`;}
function render(){photoMount?.destroy();photoMount=null;autoPhotoMount?.destroy();autoPhotoMount=null;unmountScene();unmountScene=()=>{};welcomeMount?.destroy();welcomeMount=null;rmsMount?.destroy();rmsMount=null;oralMount?.destroy();oralMount=null;libraryMount?.destroy();libraryMount=null;libraryImportMount?.destroy();libraryImportMount=null;conversation.stop();document.body.classList.toggle('montage-home',view==='home');document.body.classList.toggle('child-navigation',view!=='parent');document.body.classList.toggle('game-lesson',['mission','numbers','weekly','speed-math','school-plan','squishy'].includes(view));document.body.classList.toggle('world-young',!advanced(profile()));document.body.classList.toggle('world-older',advanced(profile()));document.body.classList.toggle('reading-aloud',speaking);const p=profile();app.innerHTML=`<header><a href="#" data-action="home" class="brand"><span class="brand-icon">a<span>✦</span></span><span>L’Atelier des mots<small>Un peu chaque jour, à ton rythme.</small></span></a><nav aria-label="Navigation principale"><button data-action="home" ${view==='home'?'aria-current="page"':''}>Mon atelier</button><button data-action="parent" ${view==='parent'?'aria-current="page"':''}>Espace parent</button></nav></header><main id="main" tabindex="-1"><div class="topline"><span class="eyebrow">LE PETIT RENDEZ-VOUS LECTURE</span><label>Je suis <select id="profile" aria-label="Choisir la lectrice">${state.profiles.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div>${!persisted?'<p class="warning" role="alert">Le navigateur refuse la sauvegarde. Les progrès seront perdus à la fermeture. Autorisez le stockage pour les conserver.</p>':''}${voiceMessage&&(view==='home'||view==='mely-grade1')?`<aside class="panel" aria-label="Lecture audio"><p role="status">${esc(voiceMessage)}</p><button data-action="test-voice">Tester la voix</button> <button data-action="system-voice">Réessayer avec la voix système</button> <button data-action="silence">Arrêter</button></aside>`:''}${view==='parent'?learnerCards():''}${view!=='home'&&view!=='parent'?`<nav class="child-toolbar" aria-label="Retour à mon monde"><button data-action="home">‹ Mon monde</button><span>${esc(childName(p))}</span></nav>`:''}${view==='french'||view==='maths'?subjectHome(p,view):view==='adventure'?travelHome(p,{compact:true}):view==='home'?montageHome(p):view==='parent'?parent(p)+travelParent(p,travelWeek||weekKey())+gardenParent(p):view==='rms-course'&&rmsEnabled(p)?'<div id="rms-root"></div>':view==='mely-grade1'&&!advanced(p)?ecranMely():view==='mini-garden'&&miniEnabled(p)?miniGarden(p,today()):view==='library'?familyLibraryScreen(p,undefined,{track:libraryTrack}):view==='speed-math'?'<div id="speed-root"></div>':view==='school-plan'?planMap(p):view==='numbers'?numbers(p):view==='squishy'?squishyMap(p):view==='weekly'?weeklyPlan():view==='sound-garden'?soundGardenMarkup({id:gardenSoundId,more:gardenMore,practiced:p.soundGardenPracticed,celebrate:gardenCelebration}):mission(p)}</main><footer><details><summary>Installer sur iPad</summary><p>Dans Safari, touche Partager, puis Sur l’écran d’accueil et Ajouter. Une connexion Internet reste nécessaire pour le tuteur IA. Le mode hors ligne n’est pas fourni.</p></details><span>✦ À petits pas, les mots grandissent.</span><span>Exercices locaux sans compte · Progrès dans ce navigateur seulement</span></footer>`;if(view==='parent')mountParentNavigation(app,parentSection,id=>{parentSection=id;});bind();welcomeMount=mountWelcomeVideo(document.querySelector('.original-welcome'));const oralRoot=document.querySelector('#oral-check-mount');if(oralRoot)oralMount=mountOralCheck(oralRoot,oralCheck,oralContext());else oralCheck.setContext(oralContext());if(readingProgress)updateReadingCue(app,lastReadingText,readingProgress);if(view==='mission'&&session?.items[session.index])mountConversation(p,session.items[session.index],{onBeforeCapture:()=>{helped=true;cleanup();render();}});if(view==='parent'){mountParentLogin({onAuthChanged:()=>{oralWordOpenKey=null;oralCheck.reset();oralCheck.refreshStatus();},onLogoutStart:()=>oralCheck.reset()});libraryImportMount=mountFamilyLibraryImport(document.querySelector('#family-library-import'),state.profiles);planMount?.destroy();planMount=mountPlanImport(p,{save:persist,refresh:render});}if(view==='library')libraryMount=mountFamilyLibrary(document.querySelector('#family-library-view'),p,{track:libraryTrack,save:persist,onTrackChange:id=>{libraryTrack=id;},onPractice:libraryPractice});if(view==='speed-math'){speedMount?.destroy();speedMount=mountSpeedMath(document.querySelector('#speed-root'),p,{save:persist,onAnswer:(q,e)=>{const result=e.help?'help':e.correct?'correct':'incorrect';answer(p,q,result,today(),'Maths');credit(p,'practice',new Date(),{subject:'Maths',result});}});}}
function home(p){const count=p.history.length;const ready=select(p,today()).length>0;return `<section class="hero"><div><span class="pill">5 à 10 minutes ensemble</span><h1>Bonjour ${esc(p.name)}.<br>On fait pousser<br><em>les mots?</em></h1><p>Des sons à découvrir, des histoires à explorer.<br>Chaque petit pas compte.</p><button class="primary" data-action="start" ${!ready?'disabled':''}>${!ready?'Les révisions sont prêtes pour un autre jour':p.calibrated?'Commencer ma mission':'Découvrir mon point de départ'} <span>→</span></button><p class="small">${p.calibrated?'Une nouvelle sélection selon tes réponses et tes révisions.':'6 petites activités, sans note et sans grade attribué.'}</p></div><div class="garden" aria-hidden="true"><span class="sun">✹</span><div class="flower f1"><span>ou</span><i></i></div><div class="flower f2"><span>ma</span><i></i></div><div class="flower f3"><span>ch</span><i></i></div><div class="ground"></div><span class="garden-note">Un jardin de découvertes</span></div></section><section class="stats" aria-label="Mes découvertes"><div><span>✧</span><strong>${count}</strong><p>activités explorées</p></div><div><span>↻</span><strong>${Object.values(p.records).filter(r=>r.due<=today()).length}</strong><p>mots et défis à revoir</p></div><div><span>♡</span><strong>À ton rythme</strong><p>avec de l’aide si tu veux</p></div></section><section class="explore"><div><span class="eyebrow">DANS TON ATELIER</span><h2>Tout un monde à lire</h2></div><div class="skill-grid">${Object.entries(skills).map(([s,label],i)=>`<article><span class="tile-icon">${['ma','ou','Aa','‿','?!','❧'][i]}</span><h3>${label}</h3><p>${['Assembler les petits morceaux','Reconnaître les sons ensemble','Lire et donner du sens','Relier les mots à l’oral','Faire vivre les phrases','Lire, imaginer et comprendre'][i]}</p><span class="small">${p.history.filter(h=>h.skill===s).length} activité(s) explorée(s)</span></article>`).join('')}</div></section>`;}
function lessonText(q,p){
 if(sceneFor(q)){session.scene??={};return `<div data-play-scene>${sceneMarkup(q,session.scene)}</div>`;}
 if(q.beginnerMath)return beginnerMathVisual(q);
 if(beginnerProfile(p)&&!q.soundTarget&&!q.miniZone&&!q.islandObjects&&!q.islandMath&&!q.travelCount&&q.skill!=='syllabes'){const pages=activityPages(q,p),i=session.page||0;return `${q.learningMode==='listening'?'<p class="reading-coach">Écoute l’histoire. Tu peux répondre sans tout lire.</p>':''}${guidedMarkup(pages[i]||pages[0],false)}${pages.length>1?`<div class="sentence-navigation"><button data-action="sentence-back" ${i===0?'disabled':''}>←</button><span>${i+1} / ${pages.length}</span><button data-action="sentence-next" ${i===pages.length-1?'disabled':''}>→</button></div>`:''}`;}
 if(q.islandObjects||q.islandMath)return islandVisual(q);

 if(q.travelCount)return travelVisual(q)+`<p>${esc(q.text)}</p>`;
 if(q.miniZone)return miniVisual(q)+guidedMarkup(spokenActivity(q),false);
 if(q.soundTarget)return `<div class="sound-target"><span class="sound-letter">${esc(q.soundTarget)}</span><p>Comme dans <strong>${esc(q.model)}</strong></p><p>🔊 Écoute le son à chercher, puis les deux choix.</p></div>`;
 const text=spokenActivity(q),parts=q.skill==='syllabes'&&q.text.includes('+')?q.text.split(/\s*\+\s*/):null;
 const recorded=!advanced(p)?syllableAudioFor(q):null;
 const pieceClips=syllablePartsFor(q);
 const strip=parts?`<div class="syllable-strip" aria-label="Morceaux à assembler">${parts.map((part,i)=>pieceClips[i]?`<button type="button" data-syllable-part="${i}" aria-label="Écouter ${esc(part)}">🔊 ${esc(part)}</button>`:`<span>${esc(part)}</span>`).join('<i aria-hidden="true">+</i>')}</div>${recorded?`<div class="reading-coach"><button type="button" data-syllable-whole="${esc(recorded.whole)}">▶ Écouter ${esc(recorded.whole)}</button><p>Écoute chaque son, puis la syllabe entière. Le signe + ne se prononce pas.</p></div>`:''}`:'';
 const grade3Help=advanced(p)&&parts?'<p class="reading-coach">Écoute les morceaux disponibles, puis touche Écouter pour entendre le mot entier. Les morceaux sans son enregistré restent visibles.</p>':'';
 const words=!advanced(p)?decodingWords(q):[];
 return (q.skill==='sons'&&['f','v'].includes(q.text)?soundCardMarkup(activeSoundCard):'')+strip+grade3Help+(parts&&!feedback?'<p class="reading-coach">🦉 Écoute les morceaux, puis assemble-les.</p>':guidedMarkup(text,advanced(p)))+(!advanced(p)&&words.length?`<div class="decode-words" aria-label="Repères oraux et écoute du mot entier">${words.map(w=>`<button data-word-audio="${esc(w)}" aria-label="Écouter le mot entier : ${esc(w)}">🔊 ${esc(w)} <small>(${syllables[w].map(esc).join(' · ')})</small></button>`).join('')}</div>`:'');
}
function mission(p){if(session.dailyDay&&session.index>=session.items.length)return `<section class="finish daily-finish">${landscape()}<div class="reward-stars" aria-hidden="true">⭐ ✨ ⭐</div><h1>Ton aventure du jour est terminée!</h1><p>Trois petits défis explorés. Bravo pour tes efforts!</p><button class="primary" data-action="home">Mon monde →</button><button data-action="adventure">Explorer notre voyage</button></section>`;if(session.items[0]?.island&&session.index>=session.items.length){const c=islandChapters.find(c=>c.id===session.items[0].island),i=islandChapters.indexOf(c),next=islandChapters[i+1];return `<section class="finish island-finish"><div class="island-sparkles" aria-hidden="true">✦ ✧ ✦</div><h1>${next?'La suite de notre histoire…':'Le livre du trésor est ouvert!'}</h1><p>${next?`Les sœurs poursuivent leur aventure : ${esc(next.title.toLowerCase())}.`:'Les sœurs découvrent un livre rempli de nouvelles histoires. Leurs ailes de licorne brillent au soleil.'}</p><p>Tes trois défis ont été explorés. Tes essais et tes réussites sont conservés.</p>${next?`<button class="primary" data-island-chapter="${next.id}">Continuer vers ${esc(next.place.toLowerCase())} →</button>`:''}<button data-action="home">Revenir à notre aventure</button></section>`;}if(session.items[0]?.miniZone&&session.index>=session.items.length)return `<section class="finish mini-garden"><div class="mini-sky" aria-hidden="true"><span>🌻</span><span>🐝</span><span>🌼</span></div><h1>Ta petite pause est arrivée!</h1><p>Trois défis explorés. Tes essais sont conservés; tu peux revenir à ton rythme.</p><button class="primary" data-action="mini-garden">Retour à mon jardin →</button><button data-action="home">Mon monde</button></section>`;if(session.squishy&&session.index>=session.items.length){const stage=squishyStages.find(s=>s.id===session.squishy);return `<section class="finish squishy-map">${blob(squishyStages.indexOf(stage))}<h1>${stage.pet} rejoint ta collection!</h1><p>Tu as exploré les deux défis. Reviens jouer pour consolider ce que tu apprends.</p><button class="primary" data-action="squishy">Retour à mon archipel →</button></section>`;}if(session.index>=session.items.length)return `<section class="finish">${landscape()}<div class="reward-stars" aria-hidden="true">⭐ ✨ ⭐</div><h1>Bravo pour ton aventure!</h1><p>${session.items.length} défis explorés. Chaque essai te fait avancer.</p><button class="primary" data-action="home">Retour à mon monde →</button></section>`;const q=session.items[session.index];return `<section class="adventure-lesson ${sceneFor(q)?'illustrated-lesson':''}">${q.island?islandScene(q):landscape()}<div class="adventure-top"><span class="world-badge">${gradeFor(p)}${gradeFor(p)===1?'re':'e'} année · ${esc(q.travelSubject||session.subject||skills[q.skill]||'Français')}</span><strong>⭐ ${session.index+1} / ${session.items.length}</strong></div><div class="adventure-layout">${companion(p)}<div class="lesson-work"><div class="lesson-heading">${q.title?`<span class="eyebrow">${esc(q.title)}</span>`:''}<h1>${esc(q.prompt)}</h1><button data-action="question-audio" class="question-audio">🔊 Écouter la question</button><progress value="${session.index}" max="${session.items.length}" aria-label="Avancement de la mission"></progress></div><div class="lesson-text">${lessonText(q,p)}</div>${!feedback&&popitExercise(q)?'<button class="lesson-popit-helper" data-popit-aid>🫧 Mon Pop-it pour ce calcul</button>':''}${audio()}${oralTargetForActivity(q)?oralWordPractice(q):''}<div class="choices">${q.choices.length?q.choices.map((c,i)=>`<div class="oral-choice"><button data-choice-audio="${i}" aria-label="Écouter le choix ${i+1}">🔊</button><button data-choice="${i}" ${feedback?'disabled':''}>${beginnerProfile(p)?`<span class="choice-picture" aria-hidden="true">${choicePicture(c)}</span>`:q.island?'':`<span class="choice-marker">${i+1}</span>`}${esc(c)}</button></div>`).join(''):`<p>Avec un adulte : comment s’est passée ta lecture?</p><button data-result="correct" ${feedback?'disabled':''}>⭐ Lu sans aide</button><button data-result="incorrect" ${feedback?'disabled':''}>🌱 Je m’exerce encore</button>`}</div>${feedback?`<div class="feedback ${answerCelebrated?'travel-bravo':''}" role="status"><strong>${answerCelebrated?'✨ Bravo! Tu as trouvé!' :feedback==='help'?'🦉 On cherche ensemble.':'🌱 Un autre essai pour apprendre.'}</strong>${feedback==='correct'?`<p class="travel-earned">${travelGained?'+5 étoiles pour cette réussite!':'Cette réussite brille déjà dans ton passeport aujourd’hui.'}</p>`:''}${answerCelebrated?`<div class="success-banner"><span aria-hidden="true">⭐ 🦉 ⭐</span><strong>Bravo !</strong><p data-success-note>Le prochain défi arrive…</p><button data-action="pause-next">Rester ici</button></div>`:''}<p>${esc(q.explanation)}</p><button data-action="explanation-audio">🔊 Réécouter</button><button data-action="retry">Réessayer</button><button class="primary" data-action="next">${session.index+1===session.items.length?'Terminer':'Continuer'} →</button></div>`:`<button class="help" data-action="help">💡 ${tutorHint?'Écouter l’explication':'Écouter un indice'}</button>`}${tutorHint?`<p class="game-hint" role="status">🦉 ${esc(localHint(q,p))}</p>`:''}<details class="tutor-details"><summary>Avec un adulte · aide et conversation</summary>${tutorPanel(q,p)}</details></div></div></section>`;}
function parent(p){return `<section class="parent"><span class="eyebrow">ACCOMPAGNER, TOUT SIMPLEMENT</span><h1>Espace parent</h1><p>Profil actif : <strong>${esc(p.name)}</strong>. Changer de lectrice sépare les progrès et les devoirs. Cet espace n’est pas protégé par un mot de passe.</p>${parentNavigation()}<section class="panel" data-parent-group="settings"><h2>Accès scolaires</h2>${schoolVocabularyLinks(p)}${schoolMathLinks(p)}${voicePicker()}</section><div class="parent-grid"><div data-parent-group="documents">${automaticPhotosPanel()}<details><summary>Conserver des photos sans préparer de jeux</summary>${schoolPhotosPanel(p)}</details><details><summary>Récupérer ou analyser un plan</summary>${planPanel(p)}</details>${familyLibraryPanel(state.profiles)}<button data-action="library">Ouvrir ses fiches et parcours</button>${!advanced(p)?'<button data-action="mely-grade1">Ouvrir son cahier de 1re année</button>':''}</div><div data-parent-group="progress">${progressPanel(p,today())}${parentCoachingPanel(p)}</div><section class="panel" data-parent-group="settings"><h2>Références et profil</h2><p>À consulter avec un adulte. Les activités de l’atelier sont originales; elles ne remplacent pas les consignes de l’école.</p><p><a href="https://www.alloprof.qc.ca/fr/eleves/bv/francais/repertoire-de-revision-${advanced(p)?'3e':'1re'}-annee-du-primaire-${advanced(p)?'f1590':'f1588'}" target="_blank" rel="noopener noreferrer">Alloprof · Français · ${advanced(p)?'3e':'1re'} année</a></p>${advanced(p)?'<p><a href="https://www.alloprof.qc.ca/fr/eleves/bv/mathematiques/repertoire-de-revision-en-mathematiques-3e-annee-primaire-m1609" target="_blank" rel="noopener noreferrer">Alloprof · Mathématiques · 3e année</a></p>':'<p><a href="https://www.alloprof.qc.ca/fr/parents/articles/favoriser-lecture-ecriture/apprendre-lecture-ecriture-k1352" target="_blank" rel="noopener noreferrer">Alloprof Parents · Apprendre à lire</a></p>'}<p><a href="https://primaire.recitus.qc.ca/" target="_blank" rel="noopener noreferrer">RÉCIT · Univers social au primaire</a></p><h2>Son petit profil</h2><form id="school-context"><label for="stage">Année scolaire (facultatif)</label><select id="stage">${['non précisé','1re année','2e année','3e année','4e année'].map(x=>`<option ${schoolContext(p).stage===x?'selected':''}>${x}</option>`).join('')}</select><label for="focus">Stratégie ou objectif choisi avec l’école</label><input id="focus" maxlength="160" value="${esc(schoolContext(p).focus)}"><button>Enregistrer le contexte</button></form><form id="rename"><label for="name">Prénom ou surnom</label><input id="name" maxlength="30" value="${esc(p.name)}" required><button class="primary">Enregistrer le nom</button></form><p>Aucun grade n’est déduit de l’âge. Le point de départ observe six domaines, puis la sélection évolue avec les réponses.</p><p>Le bilan « Son évolution » rassemble les essais distincts et les aides reçues, sans transformer les répétitions en réussite supplémentaire.</p></section><section class="panel" data-parent-group="documents"><h2>Les mots de l’école</h2><p>Collez des mots ou un court texte (5 000 caractères maximum). Une règle extrait jusqu’à 20 mots distincts pour une lecture à voix haute. Relisez la proposition avant de l’assigner.</p><form id="generate"><label for="school">Mots ou texte scolaire</label><textarea id="school" maxlength="5000" rows="6" required placeholder="Ex. : un bateau, la neige, une amie…"></textarea><button class="primary">Préparer les cartes</button></form><p class="small">Cette saisie manuelle extrait seulement les mots. L’importation photo se trouve dans Son plan de travail. Aucune question de compréhension n’est inventée pour ce texte.</p>${draft.length?`<div class="preview"><h3>À vérifier avant d’assigner</h3><p>${draft.map(q=>esc(q.text)).join(' · ')}</p><button data-action="assign">Assigner ces ${draft.length} cartes à ${esc(p.name)}</button></div>`:''}<p>${p.assignments.length} carte(s) assignée(s), proposées après le point de départ.</p>${p.assignments.length?'<button data-action="clear-assignments">Retirer les cartes scolaires</button>':''}</section><section class="panel" data-parent-group="settings"><h2>Données et confidentialité</h2><p>Progrès, noms et mots scolaires restent dans le stockage local de ce navigateur. Ils ne se synchronisent pas entre appareils. Un autre utilisateur de cet appareil peut les consulter. La navigation privée ou l’effacement du navigateur peut les supprimer.</p><p>La voix de synthèse dépend du navigateur et de ses réglages système; certaines voix peuvent utiliser un service du fournisseur. Le studio local ne transmet aucun enregistrement. La pratique orale, après connexion et confirmation de présence de l’adulte, envoie un extrait court à OpenAI pour reconnaître le mot ou le nombre. Aucun score de prononciation ni passage de niveau automatique. La conversation IA activée transmet aussi chaque phrase via le serveur.</p><button data-action="reset-profile">Effacer les données de ${esc(p.name)}</button><button class="danger" data-action="reset-all">Réinitialiser les profils et les progrès</button></section><section class="panel" data-parent-group="progress"><h2>Comment la mission s’adapte</h2><p>Six activités pour commencer, puis jusqu’à huit par mission. Une réponse avec aide ou incorrecte remet le défi à réviser dès la prochaine mission. Sans aide : révision après 1, 3, 7, puis 14 jours.</p><p>La difficulté augmente après des essais répartis sur plusieurs jours. Les répétitions de la même carte dans une journée ne suffisent pas. Après une aide ou une correction, l’essai reste accompagné; une autre journée permet de vérifier l’autonomie. Cette première banque est surtout un point de départ pour les premières années du primaire; ce n’est pas un programme complet de la 1re à la 4e année.</p></section></div></section>`;}
function finishAnswer(result){if(feedback)return;const q=session.items[session.index];const revisit=!!profile().records[q.id],beforePoints=travelPoints(profile());feedback=answer(profile(),q,attemptResult(result,helped),today(),q.travelSubject||(q.travelCount?'Maths':session.subject==='Voyage'?'Français':session.subject||'Français'));credit(profile(),'practice',new Date(),{subject:q.travelSubject||session.subject||'Français',result:feedback,revisit});travelGained=travelPoints(profile())-beforePoints;if(session.calibration&&session.index===session.items.length-1)profile().calibrated=true;answerCelebrated=result==='correct';persist();render();const activeSession=session,index=session.index;if(answerCelebrated){speakText('Bravo! Tu as bien travaillé.');cancelSuccess=scheduleSuccess(()=>{if(view==='mission'&&session===activeSession&&session.index===index&&answerCelebrated)act('next');});}else speakText(oralFeedback(q,feedback));}

function navigate(v){kaluluUnmount?.();kaluluUnmount=null;oralWordOpenKey=null;oralCheck.reset();cleanup();view=v;draft=[];session=null;feedback=null;render();document.querySelector('#main').focus();window.scrollTo(0,0);}
function bind(){
 if(view==='parent'){const id=profile().id;photoMount=mountSchoolPhotos(document.querySelector('#school-photos'),profile(),{parent:true,onPractice:game=>{if(profile().id!==id)return;if(game==='plan')return navigate('school-plan');if(game==='social')begin([socialFor(profile())],'Univers social');else libraryPractice(game);}});}
 if(view==='parent')autoPhotoMount=mountAutomaticPhotos(document.querySelector('#automatic-homework'),profile(),{save:persist,onStored:()=>photoMount?.refresh(),onOpen:()=>navigate('school-plan')});

 document.querySelector('[data-illustrated-calculation]')?.addEventListener('click',()=>{if(advanced(profile()))begin(illustratedCards(profile()),'Maths');});
 if(view==='mission'&&session?.items[session.index])unmountScene=mountScene(document.querySelector('[data-play-scene]'),session.items[session.index],session.scene??={},{onHelp:()=>{helped=true;},disabled:!!feedback});
 document.querySelector('[data-popit-aid]')?.addEventListener('click',()=>{const q=popitExercise(session?.items[session.index]);if(!q)return;reader.stop();phonemePlayer.stop();oralCheck.stop();conversation.stop();tutorVoice.stop();syllablePlayer.stop();helped=true;openPopitAid(q,{stop:()=>reader.stop()});});
 document.querySelector('[data-popit]')?.addEventListener('click',()=>{cleanup();openPopit(profile(),{save:persist,speak:speakText,stop:()=>reader.stop()});});
 document.querySelectorAll('[data-island-chapter]').forEach(b=>b.onclick=()=>begin(islandCards(profile(),b.dataset.islandChapter),'Voyage'));

 document.body.classList.toggle('travel-paused',!!travelState(profile()).quiet);
 document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{travelState(profile()).destination=b.dataset.destination;persist();render();});
 document.querySelectorAll('[data-travel-play]').forEach(b=>b.onclick=()=>begin(travelCards(profile(),b.dataset.travelPlay),'Voyage'));
 document.querySelector('[data-travel-quiet]')?.addEventListener('click',()=>{travelState(profile()).quiet=!travelState(profile()).quiet;persist();render();});
 document.querySelector('#travel-week')?.addEventListener('change',ev=>{if(ev.target.value){travelWeek=weekKey(new Date(ev.target.value+'T17:00:00Z'));render();}});
 document.querySelectorAll('[data-travel-task]').forEach(b=>b.onchange=()=>{const w=travelWeek||weekKey(),t=travelTasks(profile(),w)[Number(b.dataset.travelTask)];if(t)reviewTask(profile(),w,t.id,b.checked);persist();render();});
 document.querySelector('#travel-claim')?.addEventListener('click',()=>{claimTravel(profile(),travelWeek||weekKey(),true);persist();render();});

 if(view==='rms-course'&&rmsEnabled(profile()))rmsMount=mountRms(document.querySelector('#rms-root'),profile(),{save:persist,day:today(),speed:state.readingSpeed,voiceURI:state.readingVoiceURI,onHome:()=>navigate('home')});
 document.querySelectorAll('[data-mini-zone]').forEach(b=>b.onclick=()=>{const items=miniSession(profile(),b.dataset.miniZone,today());if(items.length)begin(items,'Maths');});
 document.querySelectorAll('[data-syllable-part]').forEach(b=>b.addEventListener('click',()=>{
  const q=session?.items?.[session.index],parts=q?syllablePartsFor(q):[];
  const part=parts[Number(b.dataset.syllablePart)];
  if(view==='mission'&&part){helped=true;playSyllable(part.category,part.id);}
 }));
 document.querySelectorAll('[data-syllable-whole]').forEach(b=>b.addEventListener('click',()=>{
  const q=session?.items?.[session.index],recorded=q&&!advanced(profile())?syllableAudioFor(q):null;
  if(view==='mission'&&recorded){helped=true;playSyllable('syllabes',recorded.whole);}
 }));
 if(view==='mely-grade1'&&!advanced(profile())){kaluluUnmount?.();kaluluUnmount=mountKalulu(document,{beforePlay:()=>{reader.stop();phonemePlayer.stop();oralCheck.stop();}});}document.querySelectorAll('[data-mely-word]').forEach(b=>b.addEventListener('click',()=>{if(!advanced(profile())&&view==='mely-grade1')speakText(b.dataset.melyWord);}));document.querySelectorAll('[data-mely-topic]').forEach(b=>b.addEventListener('click',()=>{if(advanced(profile()))return;const s=sujetsMely.find(x=>x.id===b.dataset.melyTopic);if(s)begin(exercicesMely(s.id),s.subject);}));document.querySelector('#oral-word-practice')?.addEventListener('toggle',e=>{if(!e.currentTarget.isConnected)return;oralWordOpenKey=e.currentTarget.open?profile().id+'|'+session.items[session.index].id:null;if(e.currentTarget.open&&!feedback)helped=true;if(!e.currentTarget.open)oralCheck.stop();});document.querySelectorAll('[data-plan-mission]').forEach(b=>b.onclick=()=>{const {missions}=planMissions(planFor(profile())),i=Number(b.dataset.planMission);if(missions[i]&&missionOpen(profile(),missions,i))begin(missions[i].items.slice(0,4),missions[i].subject);});document.querySelectorAll('[data-school-resource]').forEach(link=>link.addEventListener('click',()=>cleanup()));document.querySelectorAll('[data-squishy]').forEach(b=>b.onclick=()=>{const stage=squishyStages.find(s=>s.id===b.dataset.squishy);if(!stage||!stageOpen(profile(),stage))return;oralWordOpenKey=null;cleanup();session={items:stage.items,index:0,subject:stage.domain,squishy:stage.id};feedback=null;helped=false;view='mission';render();introduce();});bindSoundGarden();document.querySelectorAll('[data-sound-card]').forEach(b=>b.onclick=()=>{reader.stop();speaking=false;activeSoundCard=b.dataset.soundCard;render();});document.querySelectorAll('[data-sound-instruction]').forEach(b=>b.onclick=()=>speakText(soundCards[b.dataset.soundInstruction].instruction));document.querySelectorAll('[data-sound-reference]').forEach(b=>b.onclick=()=>{reader.stop();speaking=false;});document.querySelectorAll('[data-choice-audio]').forEach(b=>b.onclick=()=>{const q=session.items[session.index];if(['syllabes','mots'].includes(q.skill))helped=true;const choice=q.choices[Number(b.dataset.choiceAudio)];const clip=!advanced(profile())?syllableChoiceAudio(q,choice):null;if(clip)playSyllable('syllabes',clip);else speakText(choiceSpeech(choice));});document.querySelectorAll('[data-word-audio]').forEach(b=>b.onclick=()=>{helped=true;speakText(wordLesson(b.dataset.wordAudio));});document.querySelector('#reading-speed')?.addEventListener('input',e=>{const value=playbackSpeed(e.target.value);document.querySelector('#speed-value').textContent=value.toFixed(1).replace('.',',')+' ×';e.target.setAttribute('aria-valuetext',value+' fois la vitesse de départ');});document.querySelector('#reading-speed')?.addEventListener('change',e=>{state.readingSpeed=playbackSpeed(e.target.value);persist();reader.setSpeed(state.readingSpeed);});document.querySelector('#reading-voice')?.addEventListener('change',e=>{state.readingVoiceURI=e.target.value;persist();if(view==='mission')listen();else speakText('Bonjour! On prend notre temps pour lire ensemble.');});bindMontage();bindGarden();document.querySelector('#school-context')?.addEventListener('submit',e=>{e.preventDefault();profile().schoolContext={stage:document.querySelector('#stage').value,focus:document.querySelector('#focus').value.trim().slice(0,160)};persist();render();});document.querySelector('#profile').onchange=e=>{oralWordOpenKey=null;oralCheck.reset();cleanup();state.active=e.target.value;session=null;view=view==='parent'?'parent':'home';draft=[];feedback=null;persist();render();};document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>finishAnswer(Number(b.dataset.choice)===session.items[session.index].answer?'correct':'incorrect'));document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>finishAnswer(b.dataset.result));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();act(b.dataset.action);});document.querySelector('#rename')?.addEventListener('submit',e=>{e.preventDefault();profile().name=document.querySelector('#name').value.trim()||'Lectrice';persist();render();});document.querySelector('#generate')?.addEventListener('submit',e=>{e.preventDefault();draft=generate(document.querySelector('#school').value);render();});}
function act(a){if(['french','maths','adventure','sound-garden'].includes(a))return navigate(a);if(a==='words')return begin([...profile().assignments,...skillCards(profile(),'mots')],'Français');if(a==='daily-start'){oralWordOpenKey=null;cleanup();const route=dailyAdventure(profile(),today());session={items:route.items,index:route.index,subject:'Mon aventure du jour',dailyDay:route.day,calibration:false};feedback=null;helped=false;view='mission';persist();render();document.querySelector('#main').focus();window.scrollTo(0,0);if(session.items[session.index])introduce();return;}if(a==='pause-next'){cancelSuccess();document.querySelector('[data-success-note]')?.replaceChildren(document.createTextNode('Prends ton temps. Appuie sur Continuer quand tu veux.'));return;}if(a==='sentence-next'||a==='sentence-back'){const q=session.items[session.index],pages=activityPages(q,profile());cleanup();session.page=Math.max(0,Math.min(pages.length-1,(session.page||0)+(a==='sentence-next'?1:-1)));render();if(q.learningMode!=='listening')helped=true;speakText(pages[session.page]);return;}if(a==='rms-course'){if(rmsEnabled(profile()))navigate('rms-course');return;}if(a==='mini-garden'){if(miniEnabled(profile()))navigate('mini-garden');return;}if(a==='mely-grade1'){if(!advanced(profile()))navigate('mely-grade1');return;}if(a==='library'||a==='library-reading'||a==='library-numbers'){libraryTrack=a==='library-numbers'?'numbers':a==='library-reading'?'reading':'';return navigate('library');}if(a==='school-plan')return navigate('school-plan');if(a==='speed-math'){if(advanced(profile()))navigate('speed-math');return;}if(a==='squishy'){if(advanced(profile()))navigate('squishy');return;}if(a==='question-audio')return speakText(oralQuestion(session.items[session.index]));if(a==='explanation-audio')return speakText(oralFeedback(session.items[session.index],feedback));if(a==='choose-child'){gameReady=false;return navigate('home');}if(a==='weekly'){if(!advanced(profile()))return;cleanup();view='weekly';render();return;}if(a==='test-voice')return speakText('Bonjour! On prend notre temps pour lire ensemble.');if(a==='system-voice')return speakText(lastReadingText,true);if(gardenAction(a))return;if(a==='home'||a==='parent')return navigate(a);if(a==='start'){oralWordOpenKey=null;cleanup();session={items:select(profile(),today()).map(q=>beginnerCard(q,profile())),index:0,calibration:!profile().calibrated};feedback=null;helped=false;view='mission';render();document.querySelector('#main').focus();introduce();}if(a==='retry'){oralWordOpenKey=null;cleanup();feedback=null;helped=true;session.scene={};render();}if(a==='next'){oralWordOpenKey=null;cleanup();if(session.dailyDay){advanceDaily(profile(),session.dailyDay,session.index);persist();}session.index++;session.page=0;session.scene={};feedback=null;helped=false;voiceMessage='';render();document.querySelector('#main').focus();if(session.items[session.index])introduce();}if(a==='help'){if(!tutorHint){tutorHint=true;helped=true;render();speakText(localHint(session.items[session.index],profile()));}else finishAnswer('help');}if(a==='tutor-stop'){oralCheck.stop();conversation.stop();tutorVoice.stop();reader.stop();speaking=false;render();}if(a==='listen')listen();if(a==='silence'){syllablePlayer.stop();oralCheck.stop();phonemePlayer.stop();readingProgress=null;clearTimeout(nextWordTimer);nextWordTimer=null;reader.stop();speaking=false;voiceMessage='Lecture arrêtée. Tu peux réécouter quand tu veux.';render();}if(a==='record')record();if(a==='stop-record'){if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());}if(a==='assign'){profile().assignments=[...new Map([...profile().assignments,...draft].map(q=>[q.id,q])).values()];draft=[];persist();render();}if(a==='clear-assignments'){const ids=new Set(profile().assignments.map(q=>q.id));profile().assignments.forEach(q=>delete profile().records[q.id]);profile().history=profile().history.filter(h=>!ids.has(h.id));profile().assignments=[];persist();render();}if(a==='reset-profile'&&confirm(`Effacer le profil ${profile().name}, ses progrès et ses mots?`)){oralWordOpenKey=null;oralCheck.reset();cleanup();const i=state.profiles.findIndex(p=>p.id===state.active);state.profiles[i]=fresh().profiles[i];draft=[];persist();render();}if(a==='reset-all'&&confirm('Effacer les deux profils et tous les progrès? Les copies de fiches se retirent séparément dans Mes fiches Alloprof.')){cleanup();try{storage.removeItem(KEY);}catch{}state=fresh();persist();navigate('home');}}
function libraryPractice(kind,context={}){const p=profile();if(kind==='sounds'){gardenSoundId='a';gardenMore=false;return navigate('sound-garden');}if(kind==='numbers'){wholeRow=false;numberRow=firstNumberRow(p);numberIndex=0;chosenNumber=Number.isSafeInteger(context.number)&&context.number>=0&&context.number<=(advanced(p)?1999:99)?context.number:null;return navigate('numbers');}const items=kind==='reading'?storyCards(p):kind==='maths'?mathsFor(p):skillCards(p,kind==='vocabulary'?'mots':'syllabes');if(items.length)begin(items,kind==='maths'?'Maths':kind==='reading'?'Lecture':'Français');}
function introduce(){const q=session.items[session.index];speakText(oralQuestion(q),false,()=>{if(q.learningMode==='listening'&&view==='mission'&&session?.items[session.index]===q)speakText(activityPages(q,profile())[session.page||0]);});}
function playSyllable(category,name){
 reader.stop();speaking=false;phonemePlayer.stop();conversation.stop();oralCheck.stop();
 const local=category==='sons'?localPhonemeForKalulu(name):null;
 if(local){syllablePlayer.stop();phonemePlayer.play(local);return;}
 // The external Kalulu syllable URL can fail on iOS (observed for "ma").
 // Reuse the same narration service that already speaks the questions.
 // It plays a local narrated MP3 when present, or a French system voice.
 const status=msg=>{
  const el=document.querySelector('.audio-status');if(el)el.textContent=msg;
  if(category==='syllabes'&&msg.startsWith('Le son est indisponible')){
   // Do not guess a pronunciation from a bare syllable when its recording fails.
   if(el)el.textContent='Ce modèle enregistré est indisponible. Réessaie, ou écoute le mot entier avec ton adulte.';
  }
 };
 syllablePlayer.play(category,name,status);
}
function listen(){
 if(view==='mission'&&session.items[session.index].learningMode!=='listening')helped=true;
 const q=view==='mission'?session.items[session.index]:null;
 const recorded=q&&!advanced(profile())?syllableAudioFor(q):null;
 if(recorded){playSyllable('syllabes',recorded.whole);return;}
 const wholeWord=spokenActivity(session.items[session.index]).replace(/\.$/,'');
 if(!advanced(profile())&&syllables[wholeWord]){syllablePlayer.stop();speakText(wordLesson(wholeWord));return;}
 syllablePlayer.stop();if(beginnerProfile(profile()))speakText(activityPages(q,profile())[session.page||0]);else speakText(spokenActivity(session.items[session.index]));
}
function speakText(text,systemVoice=false,onEnded,fromOralCheck=false){syllablePlayer.stop();if(!fromOralCheck)oralCheck.stop();phonemePlayer.stop();clearTimeout(nextWordTimer);nextWordTimer=null;lastReadingText=text;readingProgress=null;conversation.stop();reader.speak(text,{preferredURI:state.readingVoiceURI||'',speed:state.readingSpeed,natural:isFrenchWordModel(text),systemVoice,onProgress:event=>{readingProgress=event;updateReadingCue(app,text,event);},onState:(status,message)=>{speaking=status==='starting'||status==='speaking';voiceMessage=message;if(status==='ended'||status==='error'){readingProgress=null;updateReadingCue(app,text,{charIndex:-1});}updateAudioSurface(app,{speaking,message:voiceMessage});if(status==='ended')onEnded?.();}});}
function parentAdditionGate(){const a=20+Math.floor(Math.random()*30),b=20+Math.floor(Math.random()*30);const response=window.prompt('Réservé à un adulte : combien font '+a+' + '+b+' ?\nCette question ne remplace pas une connexion parent sécurisée.');return response!==null&&response.trim()===String(a+b);}
async function record(){if(recording||micPending)return;if(!parentAdditionGate()){mediaMessage='Le microphone reste fermé. Demande à un adulte de répondre à la question.';render();return;}oralCheck.stop();reader.stop();speaking=false;conversation.stop();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){mediaMessage='Enregistrement indisponible. Utilisez HTTPS ou localhost et un navigateur compatible.';render();return;}const epoch=mediaEpoch;micPending=true;mediaMessage='Autorise le microphone si tu veux enregistrer.';render();try{const tracks=await navigator.mediaDevices.getUserMedia({audio:true});if(epoch!==mediaEpoch){tracks.getTracks().forEach(t=>t.stop());return;}micPending=false;stream=tracks;const chunks=[];recorder=new MediaRecorder(tracks);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{tracks.getTracks().forEach(t=>t.stop());if(epoch!==mediaEpoch)return;clearTimeout(recordTimer);if(recordURL)URL.revokeObjectURL(recordURL);recordURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));recording=false;mediaMessage='À toi de réécouter. Aucun score de prononciation.';render();};recorder.onerror=()=>{if(epoch!==mediaEpoch)return;cleanup();mediaMessage='L’enregistrement a échoué. Le microphone a été arrêté.';render();};recorder.start();recording=true;mediaMessage='Enregistrement en cours…';recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop();tracks.getTracks().forEach(t=>t.stop());},45000);render();}catch{if(epoch!==mediaEpoch)return;micPending=false;stream?.getTracks().forEach(t=>t.stop());mediaMessage='Microphone refusé ou indisponible. Tu peux continuer à lire sans micro.';render();}}
window.addEventListener('pagehide',()=>{oralWordOpenKey=null;oralCheck.reset();cleanup();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&view!=='speed-math'){oralWordOpenKey=null;oralCheck.reset();cleanup();if(view==='mission'||view==='rms-course')render();}});render();

function tutorPanel(q,p){return `<aside class="panel tutor" aria-label="Petit tuteur de lecture">${owl()}<h2>On cherche ensemble?</h2><p>Je peux te proposer un petit indice écrit. Prends ton temps.</p>${tutorHint?`<p role="status">${esc(localHint(q,p))}</p>`:''}<p class="small">Accompagnement local préparé · aucune réponse d’IA en direct.</p><p>${esc(schoolContext(p).stage)}${schoolContext(p).focus?' · Objectif : '+esc(schoolContext(p).focus):''}</p><div class="audio"><button data-action="tutor-stop">Arrêter le tuteur</button></div><p class="small">Voix souhaitée : douce, naturelle, en français du Québec. Aucun score de prononciation.</p></aside>`;}

function owl(){const mode=recording?'listening':speaking?'speaking':tutorHint?'help':'idle';return `<div class="owl ${mode}" role="img" aria-label="Hibou : ${ {idle:'au repos',listening:'écoute ton enregistrement local',speaking:'lecture du modèle',help:'propose un indice'}[mode]}"><div class="owl-eyes"><i></i><i></i></div><b>▾</b><span>❧</span></div><p class="small" role="status">${ {idle:'Je suis là. On prend notre temps.',listening:'Le micro enregistre; aucune analyse.',speaking:'Écoutons la narratrice.',help:'Cherchons un petit indice ensemble.'}[mode]}</p>`;}
function learnerCards(){return `<div class="learners">${state.profiles.map((p,i)=>`<button class="learner ${i?'lavender':'pink'}" data-learner="${p.id}" aria-pressed="${p.id===state.active}"><span class="avatar">${esc(settings(p).avatar)}</span><strong>${esc(p.name)}</strong><span>${esc(schoolContext(p).stage)} ${esc(settings(p).classroom)}</span></button>`).join('')}</div>`;}
function gardenHome(p){const g=settings(p),w=weekKey(),sum=summary(p,w);return `<section class="explore"><h2>Les quatre coins du jardin</h2><p>Des activités originales pour s’exercer ensemble; une petite banque, pas tout le programme scolaire.</p><div class="skill-grid">${subjects.map((s,i)=>`<button class="subject" data-subject="${i}">${['✿','📖','123','🌎'][i]}<h3>${s}</h3><span>${['Sons, syllabes, mots et orthographe','Histoires, liaisons et pauses','Nombres, ordre, additions et soustractions','Vie collective et leçons du parent'][i]}</span></button>`).join('')}</div><button data-action="numbers">Feuille de nombres du parent · lignes A à I</button></section><section class="panel"><h2>Ma semaine · ${w}</h2><p>Lecture : ${sum.reading}/${g.goal.sessions} séances de ${g.goal.minutes} minutes · Orthographe : ${sum.spelling}/${g.goal.spelling} · Efforts : ${sum.effort}/${g.goal.effort}</p><p>Demander de l’aide et revenir sur une difficulté comptent aussi. Chaque jardin pousse à son rythme.</p><p>Avec l’adulte : confirmer une séance réellement faite.</p><button data-action="reading-session">Lecture terminée (${g.goal.minutes} min)</button><button data-action="spelling-session">Orthographe pratiquée</button><p>Utilise les mots fournis par ton parent dans l’espace Français; aucune liste scolaire n’est inventée.</p>${g.tasks.map((t,i)=>`<article class="task"><strong>${esc(t.subject)} · ${esc(t.day)} · ${esc(t.text)}</strong><p>${t.due?esc(t.due)+(t.due<torontoDay()?' · Ancien devoir : révision possible':' · Date saisie par le parent'):'Sans échéance'} ${t.done?' · Fait':''}</p><button data-task="${i}" ${t.done?'disabled':''}>Confirmer la pratique</button></article>`).join('')||'<p>Le parent peut ajouter des tâches et choisir leur jour.</p>'}${Object.values(g.awards).map(a=>`<p>✦ Semaine ${a.week} : ${a.badges.map(esc).join(' · ')} ${esc(a.reward)}</p>`).join('')}</section>`;}
function gardenParent(p){const g=settings(p);return `<section class="parent-grid"><section class="panel" data-parent-group="settings"><h2>Profils et import local</h2><p>Les portraits de l’accueil restent les repères des enfants. Tu peux personnaliser leur surnom et leur symbole ici.</p><form id="garden-profile"><label>Symbole d’avatar<input name="avatar" maxlength="8" value="${esc(g.avatar)}"></label><label>Classe (facultatif)<input name="classroom" maxlength="50" value="${esc(g.classroom)}"></label><button>Enregistrer</button></form><form id="runtime-import"><label>Importer les deux profils privés (JSON local, gauche puis droite)<textarea name="json" required placeholder='[{"name":"Surnom","stage":"1re année","classroom":""},{"name":"Surnom","stage":"3e année","classroom":""}]'></textarea></label><button>Importer les noms et classes</button><p id="import-status" role="status"></p></form><p>Aucune date de naissance ou âge n’est demandé. Aucun nom privé n’est prérempli dans le code.</p></section><section class="panel" data-parent-group="week"><h2>Planning modifiable</h2><form id="task-form"><label>Tâche<input name="text" maxlength="200" required></label><label>Matière<select name="subject">${subjects.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Jour<select name="day">${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Échéance facultative<input name="due" type="date"></label><button>Ajouter la tâche</button></form>${g.tasks.map((t,i)=>`<p>${esc(t.text)} <button data-edit-task="${i}">Modifier</button><button data-remove-task="${i}">Retirer</button></p>`).join('')}</section><section class="panel" data-parent-group="documents"><h2>Leçon d’univers social du parent</h2><form id="social-form"><label>Leçon<textarea name="lesson" maxlength="5000" required>${esc(g.lesson?.text||'')}</textarea></label><label>Question<input name="question" maxlength="300" required value="${esc(g.lesson?.prompt||'')}"></label><label>Réponse attendue et explication<textarea name="explanation" maxlength="1000" required>${esc(g.lesson?.explanation||'')}</textarea></label><button>Enregistrer la leçon et la question</button></form><p>Le parent lit la réponse de l’enfant et confirme ou propose un nouvel essai. Aucune compréhension automatique.</p></section><section class="panel" data-parent-group="week"><h2>Objectifs et fin de semaine</h2><form id="goals">${[['sessions','Séances de lecture',1,14],['minutes','Minutes par séance',1,60],['spelling','Pratiques d’orthographe',1,14],['effort','Petits efforts',1,50]].map(([k,l,min,max])=>`<label>${l}<input name="${k}" type="number" min="${min}" max="${max}" required value="${g.goal[k]}"></label>`).join('')}<label>Récompense réelle facultative choisie par le parent<input name="reward" maxlength="160" value="${esc(g.goal.reward)}"></label><button>Enregistrer les objectifs accessibles</button></form><form id="award-form"><label>Lundi de la semaine terminée<input name="week" type="date" required></label><label><input name="approved" type="checkbox" required> J’ai vérifié le bilan et j’approuve la récompense.</label><button>Valider le bilan et attribuer les badges</button><p id="award-status" role="status"></p></form><p>Semaines du lundi au dimanche, heure de Toronto. Pas de classement, perte de série, paiement ni tirage. Les badges d’une semaine sont attribués une seule fois. Aucun courriel de récompense.</p></section></section>`;}
function numbers(p){const available=numberRows(p);if(!available[numberRow])numberRow=firstNumberRow(p);const values=available[numberRow],value=chosenNumber??values[numberIndex];return `<section class="lesson number-adventure">${landscape()}<div class="adventure-top"><span class="world-badge">${gradeFor(p)}${gradeFor(p)===1?'re':'e'} année · ${esc(childName(p))}</span></div><h1>${advanced(p)?'Nombres de 0 à 999 et de 1 000 à 1 999':'Mon jardin des nombres · de 0 à 99'}</h1><label>Ligne<select id="number-row">${Object.keys(available).map(k=>`<option ${k===numberRow?'selected':''}>${k}</option>`).join('')}</select></label><label>Choisis un nombre de 0 à ${advanced(p)?1999:99}<input id="chosen-number" type="number" inputmode="numeric" min="0" max="${advanced(p)?1999:99}" value="${value}"></label><button data-action="row-mode">${wholeRow?'Un nombre à la fois':'Toute la ligne'}</button><div class="reading" data-number-display>${wholeRow?values.join(' · '):value}</div><p data-number-decomposition>${value} = ${decompose(value)||'0'}</p><details><summary>Voir le nombre en mots</summary><p data-number-words>${numberWords(value)}</p></details>${speedControl()}<button data-action="number-audio">Écouter le nombre</button><button data-action="silence">Arrêter l’écoute</button><p class="audio-status number-audio-status" role="status">${esc(voiceMessage||'Écoute le nombre, puis essaie de le redire.')}</p><details class="number-audio-source"><summary>Les voix des nombres</summary><p>Les extraits de <a href="https://pedagofa.cssdm.gouv.qc.ca/1o/1o-13/" target="_blank" rel="noopener noreferrer">PédagoFA · CSSDM</a> sont associés aux nombres. La narratrice complète les morceaux manquants.</p></details>${oralPractice(wholeRow)}<div id="number-coach-mount" ${wholeRow?'hidden':''}>${numberCoachMarkup(value)}</div><details data-number-recorder><summary>Mon studio · réécouter ma voix</summary><p>Enregistre-toi pour réécouter avec un adulte. Ta voix reste sur cet appareil et s’efface en quittant l’activité.</p><button data-action="record" ${recording||micPending?'disabled':''}>Enregistrer ma voix</button><button data-action="stop-record" ${!recording?'disabled':''}>Terminer</button><p role="status">${esc(mediaMessage)}</p>${recordURL?`<audio controls src="${recordURL}"></audio>`:''}</details><button data-action="number-prev" ${numberIndex===0?'disabled':''}>Précédent</button><button data-action="number-next" ${numberIndex===9?'disabled':''}>Suivant</button><p><span data-number-position>${chosenNumber!==null?'Nombre choisi pour s’entraîner.':'Nombre '+(numberIndex+1)+'/10.'}</span> Le parent écoute toute la ligne avant de confirmer. Le retour vocal sur un nombre ne valide pas toute la ligne.</p><button data-action="row-confirm" ${chosenNumber!==null?'disabled':''}>Parent : ligne lue sans hésitation</button><button data-action="row-retry">Réessayer un autre soir</button><p role="status">${esc(settings(p).rowStatus?.[numberRow]||'Lecture à vérifier ensemble.')}</p><button data-action="library-numbers">📚 Mes fiches de nombres à mon niveau</button><button data-action="home">Retour au jardin</button></section>`;}
function begin(items,subject){items=items.map(q=>beginnerCard(q,profile(),subject));oralWordOpenKey=null;cleanup();session={items:items[0]?.island?items:adaptiveCards(profile(),items,today()),index:0,calibration:false,subject:Object.hasOwn(skills,subject)?'Français':subject};feedback=null;helped=false;view='mission';render();document.querySelector('#main').focus();introduce();}
function gardenAction(a){const p=profile(),g=settings(p);if(a==='numbers'){cleanup();numberRow=firstNumberRow(p);numberIndex=0;chosenNumber=null;view='numbers';render();return true;}if(a==='row-mode'){cleanup();voiceMessage='';chosenNumber=null;wholeRow=!wholeRow;render();return true;}if(a==='number-audio'){const input=document.querySelector('#chosen-number'),n=Number(input?.value),current=chosenNumber??numberRows(p)[numberRow][numberIndex];if(input&&(input.value===''||!Number.isInteger(n)||n<0||n>(advanced(p)?1999:99))){cleanup();voiceMessage='Choisis un nombre entier de 0 à '+(advanced(p)?1999:99)+'.';render();return true;}if(input&&n!==current){chosenNumber=n;wholeRow=false;}speakText(wholeRow?numberRows(p)[numberRow].map(numberWords).join('. '):numberWords(chosenNumber??numberRows(p)[numberRow][numberIndex]));return true;}if(a==='number-next'||a==='number-prev'){cleanup();chosenNumber=null;numberIndex=Math.max(0,Math.min(9,numberIndex+(a==='number-next'?1:-1)));render();return true;}if(a==='row-confirm'||a==='row-retry'){cleanup();g.rowStatus??={};g.rowStatus[numberRow]=a==='row-confirm'?'Parent : lecture sans hésitation confirmée le '+torontoDay():'À reprendre un autre soir, avec de l’aide si besoin.';credit(p,'practice',new Date(),{subject:'Maths',result:a==='row-confirm'?'parent-confirmed':'retry'});persist();render();return true;}if(a==='reading-session'||a==='spelling-session'){credit(p,a==='reading-session'?'reading':'spelling',new Date(),{minutes:g.goal.minutes});persist();render();return true;}return false;}
function bindGarden(){document.querySelector('#chosen-number')?.addEventListener('input',e=>{const n=Number(e.target.value),studio=document.querySelector('[data-number-recorder]'),recordedAudio=studio?.querySelector('audio');recordedAudio?.pause();recordedAudio?.remove();cleanup();if(studio){studio.querySelector('[data-action="record"]').disabled=false;studio.querySelector('[data-action="stop-record"]').disabled=true;studio.querySelector('[role="status"]').textContent='';}voiceMessage='';document.body.classList.remove('reading-aloud');if(e.target.value!==''&&Number.isInteger(n)&&n>=0&&n<=(advanced(profile())?1999:99)){chosenNumber=n;wholeRow=false;document.querySelector('[data-number-display]').textContent=String(n);document.querySelector('[data-number-decomposition]').textContent=n+' = '+(decompose(n)||'0');document.querySelector('[data-number-words]').textContent=numberWords(n);document.querySelector('[data-number-position]').textContent='Nombre choisi pour s’entraîner.';document.querySelector('[data-action="row-confirm"]').disabled=true;document.querySelector('[data-action="row-mode"]').textContent='Toute la ligne';}document.querySelector('.number-audio-status').textContent='Écoute le nombre, puis essaie de le redire.';const oralRoot=document.querySelector('#oral-check-mount');if(oralRoot)oralRoot.hidden=wholeRow;oralCheck.setContext(oralContext());const coach=document.querySelector('#number-coach-mount');if(coach){coach.hidden=wholeRow;coach.innerHTML=numberCoachMarkup(oralContext().target?.value);}});document.querySelectorAll('[data-learner]').forEach(b=>b.onclick=()=>{oralWordOpenKey=null;oralCheck.reset();cleanup();state.active=b.dataset.learner;view=view==='parent'?'parent':'home';session=null;persist();render();});document.querySelectorAll('[data-subject]').forEach(b=>b.onclick=()=>{const p=profile(),g=settings(p),i=Number(b.dataset.subject);if(i===0){const items=select(p,today()).filter(q=>q.skill!=='comprehension');begin(items.length?items:select({...p,calibrated:false},today()).filter(q=>q.skill!=='comprehension'),'Français');}if(i===1)begin(storyCards(p),'Lecture');if(i===2)begin(mathsFor(p),'Maths');if(i===3)begin(g.lesson?[socialFor(p),g.lesson]:[socialFor(p)],'Univers social');});document.querySelector('#number-row')?.addEventListener('change',e=>{cleanup();chosenNumber=null;numberRow=e.target.value;numberIndex=0;render();});const form=(id,fn)=>document.getElementById(id)?.addEventListener('submit',e=>{e.preventDefault();fn(new FormData(e.target));});form('garden-profile',f=>{Object.assign(settings(profile()),{avatar:String(f.get('avatar')).slice(0,8),classroom:String(f.get('classroom')).slice(0,50)});persist();render();});form('runtime-import',f=>{try{const data=JSON.parse(f.get('json'));if(!Array.isArray(data)||data.length!==2||!data.every(x=>typeof x.name==='string'&&x.name.trim()&&['1re année','2e année','3e année','4e année'].includes(x.stage)))throw Error();data.forEach((x,i)=>{state.profiles[i].name=x.name.slice(0,30);state.profiles[i].schoolContext={...schoolContext(state.profiles[i]),stage:x.stage};settings(state.profiles[i]).classroom=String(x.classroom||'').slice(0,50);});persist();render();document.querySelector('#import-status').textContent='Profils importés localement.';}catch{document.querySelector('#import-status').textContent='JSON invalide : deux profils avec name et stage sont requis.';}});form('task-form',f=>{const task={text:String(f.get('text')).slice(0,200),subject:f.get('subject'),day:f.get('day'),due:f.get('due'),done:false};if(editTaskIndex===null)settings(profile()).tasks.push(task);else settings(profile()).tasks[editTaskIndex]=task;editTaskIndex=null;persist();render();});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const t=settings(profile()).tasks[Number(b.dataset.task)];if(!t.done){t.done=true;credit(profile(),'practice',new Date(),{subject:t.subject});persist();render();}});document.querySelectorAll('[data-remove-task]').forEach(b=>b.onclick=()=>{settings(profile()).tasks.splice(Number(b.dataset.removeTask),1);persist();render();});document.querySelectorAll('[data-edit-task]').forEach(b=>b.onclick=()=>{const t=settings(profile()).tasks[Number(b.dataset.editTask)],f=document.querySelector('#task-form');for(const key of ['text','subject','day','due'])f.elements[key].value=t[key];editTaskIndex=Number(b.dataset.editTask);f.scrollIntoView();});form('social-form',f=>{settings(profile()).lesson={id:'parent-social',skill:'comprehension',level:1,text:String(f.get('lesson')).slice(0,5000),prompt:String(f.get('question')).slice(0,300),explanation:String(f.get('explanation')).slice(0,1000),choices:[],answer:null};persist();render();});form('goals',f=>{const g=settings(profile());for(const k of ['sessions','minutes','spelling','effort'])g.goal[k]=Number(f.get(k));g.goal.reward=String(f.get('reward')).slice(0,160);persist();render();});form('award-form',f=>{const w=f.get('week'),result=award(profile(),w,f.get('approved')==='on');persist();document.querySelector('#award-status').textContent=result?JSON.stringify(result.summary)+' · '+result.badges.join(' · ')+' · '+result.reward:'Semaine non terminée, lundi invalide ou aucun objectif atteint. Les efforts restent enregistrés.';});}

function montageHome(p){if(gameReady)return childHome(p,today());return `<section class="choose-world original-welcome welcome-direct"><h1 class="welcome-accessible">Qui part à l’aventure?</h1><div class="choose-art"><img src="/icons/accueil-famille.png" alt="Mely-Ann à gauche dans son jardin, Liana à droite avec son livre. Choisis une activité sur l’illustration." width="1448" height="1086"><video data-welcome-video class="welcome-video" src="/icons/accueil-anime.mp4" poster="/icons/accueil-famille.png" muted loop playsinline preload="none" aria-hidden="true" tabindex="-1"></video><span class="welcome-glow" aria-hidden="true"></span><nav class="welcome-picture-links" aria-label="Choisir son monde et ses activités"><button class="picture-link picture-parent" data-action="parent" aria-label="Espace parent" title="Espace parent"></button><button class="picture-link picture-start picture-mely" data-game-child="0" aria-label="Entrer dans le monde de ${esc(childName(state.profiles[0]))}" title="Mon monde"></button><button class="picture-link picture-start picture-liana" data-game-child="1" aria-label="Entrer dans le monde de ${esc(childName(state.profiles[1]))}" title="Mon monde"></button><button class="picture-link picture-sounds" data-welcome-child="0" data-welcome-route="sounds" aria-label="Mely-Ann : les sons" title="Les sons"></button><button class="picture-link picture-syllables" data-welcome-child="0" data-welcome-route="syllables" aria-label="Mely-Ann : les syllabes" title="Les syllabes"></button><button class="picture-link picture-reading" data-welcome-child="1" data-welcome-route="reading" aria-label="Liana : lecture" title="Lecture"></button><button class="picture-link picture-numbers" data-welcome-child="1" data-welcome-route="numbers" aria-label="Liana : les nombres" title="Les nombres"></button></nav></div><label class="welcome-motion"><input type="checkbox" checked aria-label="Animations douces de l’accueil"> Animations douces</label></section>`;}

function bindMontage(){mountWelcomeMagic(document.querySelector('.welcome-direct'));document.querySelectorAll('[data-welcome-route]').forEach(b=>b.onclick=()=>{oralWordOpenKey=null;oralCheck.reset();cleanup();state.active=state.profiles[Number(b.dataset.welcomeChild)].id;gameReady=true;persist();const route=b.dataset.welcomeRoute;if(route==='sounds'){gardenSoundId='a';gardenMore=false;return navigate('sound-garden');}if(route==='numbers'){wholeRow=false;numberRow=firstNumberRow(profile());numberIndex=0;chosenNumber=null;return navigate('numbers');}begin(route==='reading'?storyCards(profile()):skillCards(profile(),'syllabes'),route==='reading'?'Lecture':'Français');});document.querySelectorAll('[data-week-table]').forEach(b=>b.onclick=()=>{if(advanced(profile()))begin(tablePractice(Number(b.dataset.weekTable),document.querySelector('#week-operation')?.value||'+'),'Maths · tables de la semaine');});document.querySelectorAll('[data-game-child]').forEach(b=>b.onclick=()=>{oralWordOpenKey=null;oralCheck.reset();cleanup();const i=Number(b.dataset.gameChild);state.active=state.profiles[i].id;gameReady=true;view='home';persist();render();window.scrollTo(0,0);});document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{
 if(b.dataset.child!==undefined&&state.profiles[Number(b.dataset.child)]?.id!==state.active)return;cleanup();
 const action=b.dataset.scene,p=profile();
 if(action==='start')return act('start');
 if(action==='numbers'){wholeRow=false;numberRow=firstNumberRow(p);numberIndex=0;chosenNumber=null;return navigate('numbers');}
 if(action==='listen')return speakText('trois cent sept');
 if(action==='reading')return begin(storyCards(p),'Lecture');
 if(action==='sounds'){gardenSoundId='a';gardenMore=false;return navigate('sound-garden');}
 if(action==='syllables'){const skill=action==='sounds'?'sons':'syllabes';const items=skillCards(p,skill);return begin(items.length?items:select(p,today()),skill);}
 const q={id:'montage-number-307',skill:'mots',level:1,text:'307',prompt:'Lis ce nombre à voix haute',explanation:'307 se lit trois cent sept : trois centaines, zéro dizaine et sept unités.',choices:[],answer:null};
 begin([q],'Lecture de nombres');
 if(action==='record')record();
 if(action==='talk')document.querySelector('.tutor')?.scrollIntoView({behavior:'smooth',block:'start'});
 });}

function weeklyPlan(){return `<section class="weekly-plan" aria-label="Plan de travail de Liana"><h2>🦉 ${schoolWeek.title}</h2><p>Mon défi : les tables de 1 à 6</p><label>Je pratique <select id="week-operation"><option value="+">les additions</option><option value="−">les soustractions</option></select></label><div class="weekly-tables">${[1,2,3,4,5,6].map(n=>`<button data-week-table="${n}" aria-label="Pratiquer la table de ${n}">${n}</button>`).join('')}</div><p>Pratique libre sans chronomètre · Le sprint est disponible ci-dessous</p><details><summary>Voir mon plan avec un parent</summary><ul>${schoolWeek.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>Les exercices proposés sont des entraînements originaux. Les devoirs du cahier restent à faire.</p></details>${schoolMathLinks(profile())}</section>`;}

function bindSoundGarden(){
 document.querySelector('[data-garden-listen]')?.addEventListener('click',()=>{cleanup();phonemePlayer.play(gardenSoundId);});
 document.querySelectorAll('[data-garden-sound]').forEach(b=>b.onclick=()=>{cleanup();gardenSoundId=b.dataset.gardenSound;render();});
 document.querySelector('[data-garden-welcome]')?.addEventListener('click',()=>speakText(gardenWelcome));
 document.querySelector('[data-garden-explain]')?.addEventListener('click',()=>speakText(gardenSelection(gardenSoundId).instruction));
 document.querySelector('[data-garden-reference]')?.addEventListener('click',()=>{cleanup();});
 document.querySelector('[data-garden-practice]')?.addEventListener('click',()=>{cleanup();profile().soundGardenPracticed=gardenPractice(profile().soundGardenPracticed,gardenSoundId);persist();gardenCelebration=true;speakText(gardenEncouragement);});
 document.querySelector('[data-garden-next]')?.addEventListener('click',()=>{cleanup();const list=gardenMore?gardenSounds:gardenSounds.slice(0,12);gardenSoundId=list[(list.findIndex(c=>c.id===gardenSoundId)+1)%list.length].id;render();});
 document.querySelector('[data-garden-more]')?.addEventListener('click',()=>{cleanup();gardenMore=!gardenMore;if(!gardenMore&&!gardenSounds.slice(0,12).some(c=>c.id===gardenSoundId))gardenSoundId='a';render();});
 document.querySelector('[data-garden-exercises]')?.addEventListener('click',()=>{cleanup();begin(skillCards(profile(),'sons'),'sons');});
}
